async () => {
  const sleep = ms => new Promise(r=>setTimeout(r,ms));
  const q = s => { const m = window.MinigameFramework.currentMinigame; return m && m.container && m.container.querySelector(s); };
  const end = Date.now() + 60000;
  while (Date.now() < end) { const f = q('.tri-finish'); if (f && !f.disabled && f.offsetParent) { await sleep(1200); break; } await sleep(120); }
  const end2 = Date.now() + 60000;
  while (Date.now() < end2) { const f = q('.tri-finish'); if (f && !f.disabled) { f.click(); return true; } await sleep(150); }
  return false;
}
